-- Parent Table
CREATE TABLE parent_table (
    age NUMBER NOT NULL,
    sex VARCHAR2(6) NOT NULL,
    PRIMARY KEY (age, sex)
);


COMMIT;

-- Social Media Table
CREATE TABLE social_media_table (
    unique_id NUMBER NOT NULL,
    age NUMBER NOT NULL,
    sex VARCHAR2(6) NOT NULL,
    sns_use_length NUMBER,
    sns_use_daily NUMBER,
    sns_use_case NUMBER,
    sns_friends NUMBER,
    sns_personal NUMBER,
    sns_content VARCHAR2(29),
    sns_good NUMBER,
    sns_believe NUMBER,
    peer_pressure NUMBER,
    sns_influence NUMBER,
    sns_wellbeing NUMBER,
    PRIMARY KEY (unique_id),
    FOREIGN KEY (age, sex) REFERENCES parent_table (age, sex)
);


-- Mental Health Table
CREATE TABLE mental_health_table (
    unique_id NUMBER NOT NULL,
    age NUMBER NOT NULL,
    sex VARCHAR2(6) NOT NULL,
    general_health NUMBER,
    phq_score NUMBER,
    gad7_score NUMBER,
    hopeless NUMBER,
    overwhelmed NUMBER,
    exhausted NUMBER,
    sad NUMBER,
    rly_sad NUMBER,
    considered NUMBER,
    attempted NUMBER,
    depression_diagnosis NUMBER,
    therapy NUMBER,
    depression_medication NUMBER,
    acha_12months_any_comp NUMBER,
    student NUMBER,
    PRIMARY KEY (unique_id),
    FOREIGN KEY (age, sex) REFERENCES parent_table (age, sex)
);

